          <button id="submitBtn">Request discovery</button>
          <div class="small">Or call <a href="tel:{{PHONE}}" style="color:var(--accent)">{{PHONE}}</a></div>
        </div>

      </form>

      <div class="summary" id="summary">
        <div style="font-weight:700;color:#e9fff6">Summary</div>
        <div class="note">No commitment—after you request, we will reach out to confirm scheduling and next steps.</div>
      </div>

      <div class="note" style="margin-top:12px">Please be aware: our consultations are educational. If you have urgent medical concerns, contact local emergency services or your primary care provider.</div>
    </div>
