  <script>
    // Simple mock slot selection
    (function(){
      const slots = [
        'Mon 9:00 AM','Mon 2:00 PM','Tue 10:30 AM','Wed 4:00 PM','Thu 11:00 AM','Fri 1:00 PM'
      ];
      const container = document.getElementById('slots');
      let selected = null;
      slots.forEach(s=>{
        const el = document.createElement('div'); el.className='slot'; el.textContent = s; el.tabIndex=0;
        el.addEventListener('click', ()=> selectSlot(el,s));
        el.addEventListener('keydown',(e)=>{ if(e.key==='Enter') selectSlot(el,s); });
        container.appendChild(el);
      });
      function selectSlot(el,s){
        document.querySelectorAll('.slot').forEach(x=>x.classList.remove('selected'));
        el.classList.add('selected'); selected = s; updateSummary();
      }
      function updateSummary(){
        const name = document.getElementById('name').value || '—';
        const goal = document.getElementById('goal').value || '—';
        document.getElementById('summary').innerHTML = '<div style="font-weight:700;color:#e9fff6">Summary</div>'+
          '<div class="note">Name: '+escapeHtml(name)+'<br>Goal: '+escapeHtml(goal)+'<br>Selected time: '+(selected||'—')+'</div>';
      }
      ['name','goal'].forEach(id=>document.getElementById(id).addEventListener('input', updateSummary));
      // submit handler (local stub)
      document.getElementById('submitBtn').addEventListener('click', function(){
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        if(!name || !email){ alert('Please provide name and email to request a discovery.'); return; }
        const payload = {name:name,email:email,phone:document.getElementById('phone').value,goal:document.getElementById('goal').value,notes:document.getElementById('notes').value,slot:selected};
        // For this local template we simply show a confirmation UI.
        document.getElementById('summary').innerHTML = '<div style="font-weight:700;color:#e9fff6">Request sent</div><div class="note">Thanks, '+escapeHtml(name)+'. We will follow up at '+escapeHtml(email)+'.</div>';
        this.disabled = true; this.textContent='Requested';
      });
      function escapeHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
    })();
  </script>
